fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Helper function: S(k) as defined in the spec, k >= 0
    fn S(k: i64) -> i64 {
        if k % 2 == 0 {
            k / 2
        } else {
            -((k + 1) / 2)
        }
    }

    // For each query (l, r), return S(r) - S(l-1)
    queries
        .into_iter()
        .map(|(l, r)| {
            // Convert to i64 for computation (prevent overflow, signed)
            let l_int = l as i64;
            let r_int = r as i64;

            (S(r_int) - S(l_int - 1)) as i8
        })
        .collect()
}